/**
 * AlphaESS-Modell aktualisieren
 *
 * Nimmt die drei Ausgänge der AlphaESS-Modbus-Node entgegen
 * (msg.source per Change-Node gesetzt):
 *
 *   "data"     Ausgang 1: Echtzeitdaten inkl. daily, yesterday, details, info
 *   "alarm"    Ausgang 2: Alarme / Warnungen
 *   "command"  Ausgang 3: Antwort auf Schreibbefehle
 *
 * Speichert die letzten Daten sowie einen 24-h-Verlauf (2-Minuten-Mittelwerte)
 * im Context-Store "file", damit alles einen Neustart übersteht.
 *
 * Vorzeichen im Verlauf:
 *   grid  > 0 = Netzbezug,      < 0 = Einspeisung
 *   batt  > 0 = Entladen,       < 0 = Laden
 */

const STORE = "file";
const BUCKET_MS = 2 * 60 * 1000;     // 2-Minuten-Raster
const HISTORY_MAX = 720;             // 24 h
const ALARM_LOG_MAX = 100;

// --------------------------------------------------
// Context mit Fallback auf Standard-Store
// --------------------------------------------------

function load(key, fallback) {
    try {
        const v = flow.get(key, STORE);
        return v === undefined ? fallback : v;
    } catch (e) {
        const v = flow.get(key);
        return v === undefined ? fallback : v;
    }
}

function save(key, value) {
    try {
        flow.set(key, value, STORE);
    } catch (e) {
        flow.set(key, value);
    }
}

function num(value) {
    if (value === null || value === undefined || value === "") {
        return null;
    }
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
}

// Alarm-/Warnungseintrag in lesbaren Text wandeln
function itemText(item) {
    if (typeof item === "string") {
        return item;
    }
    if (item && typeof item === "object") {
        return String(item.textDe || item.text || item.message || item.name || item.code || JSON.stringify(item));
    }
    return String(item);
}

const now = Date.now();
const model = load("alphaDash", null) || { data: null, lastDataAt: null, alarm: null, alarmLog: [] };
let history = load("alphaDashHistory", []);

// --------------------------------------------------
// Ausgang 1: Echtzeitdaten
// --------------------------------------------------

if (msg.source === "data") {

    const p = msg.payload;

    if (!p || typeof p !== "object") {
        node.status({ fill: "yellow", shape: "ring", text: "Daten ohne Objekt-Payload" });
        return null;
    }

    model.data = p;
    model.lastDataAt = new Date(now).toISOString();

    // Leistungswerte für den Verlauf
    const pv = num(p.modules) ?? num(p.details?.inverter?.pvPowerTotal);
    const load_ = num(p.consumption);
    const grid = num(p.grid);

    let batt = null;
    const charge = num(p.batteryCharge);
    const discharge = num(p.batteryDischarge);

    if (charge !== null || discharge !== null) {
        batt = (discharge || 0) - (charge || 0);
    } else if (num(p.battery) !== null) {
        batt = num(p.battery);
    }

    const soc = num(p.soc);

    // In 2-Minuten-Bucket mitteln
    const bucket = Math.floor(now / BUCKET_MS) * BUCKET_MS;
    const last = history[history.length - 1];
    const values = { pv, load: load_, grid, batt, soc };

    if (last && last.t === bucket) {

        const k = last.n || 1;

        for (const [key, v] of Object.entries(values)) {
            if (v === null) {
                continue;
            }
            last[key] = last[key] === null || last[key] === undefined
                ? v
                : Math.round(((last[key] * k + v) / (k + 1)) * 10) / 10;
        }

        last.n = k + 1;

    } else {
        history.push({ t: bucket, ...values, n: 1 });
    }

    const limit = now - 24 * 3600 * 1000;
    history = history.filter(h => h.t >= limit).slice(-HISTORY_MAX);
}

// --------------------------------------------------
// Ausgang 2: Alarme / Warnungen
// --------------------------------------------------

if (msg.source === "alarm") {

    const p = msg.payload || {};
    const alarms = (Array.isArray(p.alarms) ? p.alarms : []).map(itemText);
    const warnings = (Array.isArray(p.warnings) ? p.warnings : []).map(itemText);
    const signature = JSON.stringify([alarms, warnings]);

    if (!model.alarm || model.alarm.signature !== signature) {

        model.alarmLog.unshift({
            at: new Date(now).toISOString(),
            alarms,
            warnings,
            cleared: alarms.length === 0 && warnings.length === 0
        });

        model.alarmLog = model.alarmLog.slice(0, ALARM_LOG_MAX);
    }

    model.alarm = { alarms, warnings, signature, at: new Date(now).toISOString() };
}

// --------------------------------------------------
// Ausgang 3: Antwort auf Schreibbefehle
// --------------------------------------------------

if (msg.source === "command") {

    const written = Array.isArray(msg.written) ? msg.written.length : null;
    const topic = msg.topic || "";

    let de;
    let en;

    if (msg.unchanged === true) {
        de = `${topic}: keine Änderung erforderlich`;
        en = `${topic}: no change required`;
    } else if (written !== null) {
        de = `${topic}: ${written} Register geschrieben`;
        en = `${topic}: ${written} registers written`;
    } else {
        de = `${topic}: Antwort der Anlage erhalten`;
        en = `${topic}: response received`;
    }

    flow.set("alphaFeedback", { ts: now, ok: true, de, en });
}

save("alphaDash", model);
save("alphaDashHistory", history);

node.status({
    fill: "green",
    shape: "dot",
    text: `${msg.source} · ${history.length} Verlaufspunkte`
});

return { trigger: true };

/**
 * Dashboard-Modell erzeugen (entprellt)
 *
 * Fasst Daten, Alarme, Verlauf, Freischaltung und Rückmeldungen
 * zu EINER Nachricht zusammen. Dadurch zeigt das Dashboard nach
 * einem Browser-Reload immer den vollständigen Zustand.
 */

const DEBOUNCE_MS = 300;
const STORE = "file";

function load(key, fallback) {
    try {
        const v = flow.get(key, STORE);
        return v === undefined ? fallback : v;
    } catch (e) {
        const v = flow.get(key);
        return v === undefined ? fallback : v;
    }
}

function build() {

    const model = load("alphaDash", null) || {};
    const history = load("alphaDashHistory", []);
    const armedUntil = flow.get("alphaArmedUntil") || 0;
    const now = Date.now();

    const age = model.lastDataAt ? Math.round((now - Date.parse(model.lastDataAt)) / 1000) : null;

    node.status({
        fill: age === null ? "grey" : age < 120 ? "green" : "yellow",
        shape: "dot",
        text: age === null ? "Warte auf Daten" : `Daten vor ${age} s · ${history.length} Punkte`
    });

    return {
        payload: {
            data: model.data || null,
            lastDataAt: model.lastDataAt || null,
            alarm: model.alarm || null,
            alarmLog: (model.alarmLog || []).slice(0, 30),
            history: history.map(h => ({ t: h.t, pv: h.pv, load: h.load, grid: h.grid, batt: h.batt, soc: h.soc })),
            armed: armedUntil > now,
            armedUntil,
            feedback: flow.get("alphaFeedback") || null
        }
    };
}

const timer = context.get("timer");

if (timer) {
    clearTimeout(timer);
}

context.set("timer", setTimeout(() => {
    context.set("timer", null);
    node.send(build());
}, DEBOUNCE_MS));

return null;

/**
 * Befehl prüfen & senden (Sicherheitsprüfung)
 *
 * Eingang vom Dashboard: msg.payload = { action, ... }
 *
 *   action "read" | "readInfo"                 – nur lesend, immer erlaubt
 *   action "arm"          value true|false     – Steuerung 10 min freischalten
 *   action "dispatch"     power, soc, duration – Laden (< 0) / Entladen (> 0)
 *   action "dispatchStop"
 *   action "feedIn"       value 0–100 %
 *   action "timePeriod"   flag, chargeCutSoc, upsReserveSoc, charge1/2, discharge1/2
 *
 * Schreibbefehle nur, wenn
 *   - die Steuerung serverseitig freigeschaltet ist (10 Minuten),
 *   - confirm === true (zweistufige Bestätigung im Dashboard),
 *   - alle Werte plausibel sind.
 *
 * Ausgang 1: Befehl an die AlphaESS-Node (topic + payload)
 * Ausgang 2: Trigger für "Dashboard-Modell erzeugen"
 *
 * Zusätzlich muss in der AlphaESS-Node "Allow write access" aktiv sein.
 */

const ARM_MS = 10 * 60 * 1000;

const cmd = msg.payload || {};
const now = Date.now();

function feedback(ok, de, en) {
    flow.set("alphaFeedback", { ts: now, ok, de, en });
    node.status({ fill: ok ? "green" : "red", shape: "dot", text: de });
}

function reject(de, en) {
    feedback(false, de, en);
    return [null, { trigger: true }];
}

function send(topic, payload, de, en) {
    feedback(true, de, en);
    const out = { topic };
    if (payload !== undefined) {
        out.payload = payload;
    }
    return [out, { trigger: true }];
}

const finite = v => v !== null && v !== "" && Number.isFinite(Number(v));
const between = (v, a, b) => finite(v) && Number(v) >= a && Number(v) <= b;
const isTime = v => typeof v === "string" && /^([01]\d|2[0-3]):[0-5]\d$/.test(v);

// --------------------------------------------------
// Lesende Befehle und Freischaltung
// --------------------------------------------------

if (cmd.action === "read" || cmd.action === "readInfo") {
    return send(cmd.action, undefined, "Daten werden gelesen", "Reading data");
}

if (cmd.action === "arm") {
    const on = cmd.value === true;
    flow.set("alphaArmedUntil", on ? now + ARM_MS : 0);
    feedback(true,
        on ? "Steuerung für 10 Minuten freigeschaltet" : "Steuerung gesperrt",
        on ? "Controls unlocked for 10 minutes" : "Controls locked");
    return [null, { trigger: true }];
}

// --------------------------------------------------
// Schreibende Befehle: Freischaltung + Bestätigung
// --------------------------------------------------

const writeActions = ["dispatch", "dispatchStop", "feedIn", "timePeriod"];

if (!writeActions.includes(cmd.action)) {
    return reject(`Unbekannter Befehl ${cmd.action}`, `Unknown command ${cmd.action}`);
}

if ((flow.get("alphaArmedUntil") || 0) <= now) {
    return reject("Blockiert: Steuerung ist nicht freigeschaltet", "Blocked: controls are locked");
}

if (cmd.confirm !== true) {
    return reject("Blockiert: keine Bestätigung", "Blocked: not confirmed");
}

switch (cmd.action) {

    case "dispatchStop":
        return send("dispatchStop", undefined, "Dispatch-Stopp gesendet", "Dispatch stop sent");

    case "dispatch": {

        const power = Number(cmd.power);

        if (!finite(cmd.power) || power === 0 || Math.abs(power) > 100000) {
            return reject("Ungültige Dispatch-Leistung", "Invalid dispatch power");
        }
        if (!between(cmd.soc, 0, 100)) {
            return reject("Ungültiger Ziel-SOC", "Invalid target SOC");
        }
        if (!between(cmd.duration, 10, 86400)) {
            return reject("Ungültige Dauer (10 s – 24 h)", "Invalid duration (10 s – 24 h)");
        }

        const payload = {
            power: Math.round(power),
            soc: Number(cmd.soc),
            duration: Math.round(Number(cmd.duration)),
            mode: 2
        };

        const dir = power < 0 ? "Laden" : "Entladen";
        const dirEn = power < 0 ? "charge" : "discharge";

        return send("dispatch", payload,
            `Dispatch gesendet: ${dir} ${Math.abs(payload.power)} W bis ${payload.soc} %`,
            `Dispatch sent: ${dirEn} ${Math.abs(payload.power)} W to ${payload.soc} %`);
    }

    case "feedIn": {

        if (!between(cmd.value, 0, 100)) {
            return reject("Einspeisegrenze muss 0–100 % sein", "Feed-in limit must be 0–100 %");
        }

        const value = Math.round(Number(cmd.value));

        return send("feedIn", value,
            `Einspeisegrenze ${value} % gesendet`,
            `Feed-in limit ${value} % sent`);
    }

    case "timePeriod": {

        if (![0, 1, 2, 3].includes(Number(cmd.flag))) {
            return reject("Ungültige Zeitfenster-Betriebsart", "Invalid time-period mode");
        }
        if (!between(cmd.chargeCutSoc, 0, 100) || !between(cmd.upsReserveSoc, 0, 100)) {
            return reject("SOC-Werte müssen 0–100 % sein", "SOC values must be 0–100 %");
        }

        const payload = {
            flag: Number(cmd.flag),
            chargeCutSoc: Number(cmd.chargeCutSoc),
            upsReserveSoc: Number(cmd.upsReserveSoc)
        };

        for (const key of ["charge1", "charge2", "discharge1", "discharge2"]) {

            const slot = cmd[key];

            if (!slot || !isTime(slot.start) || !isTime(slot.stop)) {
                return reject("Zeiten müssen HH:MM sein", "Times must use HH:MM");
            }

            payload[key] = { start: slot.start, stop: slot.stop };
        }

        return send("timePeriod", payload, "Zeitfenster gesendet", "Time periods sent");
    }
}

return reject("Unbekannter Fehler", "Unknown error");
